#include "gpupowerdialog.h"
#include "studiobutton.h"
#include <QtWidgets>
#include <cmath>
namespace{
QString measure(double value,const QString &unit){return value<0?QString("н/д"):QString::number(value,'f',1)+unit;}
QLabel *plainLabel(){auto label=new QLabel;label->setTextFormat(Qt::PlainText);label->setWordWrap(true);return label;}
}
GpuPowerDialog::GpuPowerDialog(QWidget *parent,ModelPerformance *stats,const QString &executable,GpuPowerService *shared):QDialog(parent),ownedService(this,executable),service(shared?*shared:ownedService),performance(stats){
    setObjectName("gpuPowerWindow");setWindowTitle("Мощность GPU · Llama Studio");resize(850,650);auto root=new QVBoxLayout(this);auto tabs=new QTabWidget;root->addWidget(tabs,1);auto page=new QWidget;auto layout=new QVBoxLayout(page);auto title=new QLabel("Лимит мощности NVIDIA");title->setObjectName("title");layout->addWidget(title);
    auto row=new QHBoxLayout;gpu=new QComboBox;gpu->setObjectName("powerGpu");gpu->setSizeAdjustPolicy(QComboBox::AdjustToMinimumContentsLengthWithIcon);gpu->setMinimumContentsLength(25);row->addWidget(gpu,1);refresh=new StudioButton("Обновить");row->addWidget(refresh);layout->addLayout(row);details=plainLabel();details->setObjectName("powerDetails");details->setTextInteractionFlags(Qt::TextSelectableByMouse);layout->addWidget(details);
    auto form=new QFormLayout;watts=new QDoubleSpinBox;watts->setObjectName("powerWatts");watts->setDecimals(1);watts->setSingleStep(5);watts->setSuffix(" Вт");form->addRow("Новый лимит",watts);preset=new QComboBox;preset->setObjectName("powerPreset");preset->addItem("Вручную",0);for(int value:{100,90,80,70})preset->addItem(QString("%1% заводского лимита").arg(value),value);form->addRow("Заготовка",preset);layout->addLayout(form);ratio=plainLabel();layout->addWidget(ratio);
    auto actions=new QHBoxLayout;apply=new StudioButton("Применить лимит");apply->setObjectName("applyPowerLimit");restore=new StudioButton("Вернуть заводской");restore->setObjectName("restorePowerLimit");actions->addWidget(apply);actions->addWidget(restore);actions->addStretch();layout->addLayout(actions);
    auto scope=plainLabel();scope->setText("Лимиты сохраняются в текущем JSON-профиле и применяются перед запуском сервера. При обычном выходе из программы изменённые карты возвращаются к заводским лимитам. Если профиль ещё не создан, выполните «Сохранить как…» в главном окне. Изменение действует на всю GPU; могут требоваться права администратора.");layout->addWidget(scope);modelStats=plainLabel();modelStats->setObjectName("powerModelStats");layout->addWidget(modelStats);status=plainLabel();status->setObjectName("powerStatus");status->setText("Чтение возможностей драйвера…");layout->addWidget(status);layout->addStretch();tabs->addTab(page,"Управление");
    auto guide=new QTextBrowser;guide->setObjectName("gpuPowerGuide");guide->setOpenExternalLinks(true);guide->setSource(QUrl("qrc:/gpu-power-guide.html"));tabs->addTab(guide,"Баланс температуры и скорости");auto close=new StudioButton("Закрыть");root->addWidget(close,0,Qt::AlignRight);connect(close,&QPushButton::clicked,this,&QDialog::close);
    connect(refresh,&QPushButton::clicked,this,[this]{status->setText("Обновление…");service.refresh();});
    connect(gpu,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{dirty=false;updateControls();});
    connect(watts,qOverload<double>(&QDoubleSpinBox::valueChanged),this,[this]{dirty=true;QSignalBlocker block(preset);preset->setCurrentIndex(0);updateRatio();});
    connect(preset,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{const auto card=selected();if(!card||preset->currentData().toInt()==0||card->defaultLimit<=0)return;const auto desired=std::round(card->defaultLimit*preset->currentData().toInt()/10.0)/10.0;QSignalBlocker block(watts);watts->setValue(qBound(card->minimum,desired,card->maximum));dirty=true;updateRatio();});
    connect(apply,&QPushButton::clicked,this,[this]{if(!selected())return;applying=true;status->setText("Проверка диапазона, применение и чтение фактического лимита…");service.apply(gpu->currentData().toString(),watts->value());});
    connect(restore,&QPushButton::clicked,this,[this]{if(!selected())return;applying=true;status->setText("Возврат заводского лимита и проверка результата…");service.restoreDefault(gpu->currentData().toString());});
    connect(&service,&GpuPowerService::readingsChanged,this,&GpuPowerDialog::updateDevices);
    connect(&service,&GpuPowerService::busyChanged,this,[this](bool){updateControls();});
    connect(&service,&GpuPowerService::completed,this,[this](bool ok,const QString &message){if(applying||!ok||status->text()==QString::fromUtf8("Обновление…")||status->text()==QString::fromUtf8("Чтение возможностей драйвера…"))status->setText(message);if(applying&&ok)dirty=false;applying=false;updateControls();});
    if(performance)connect(performance,&ModelPerformance::changed,this,&GpuPowerDialog::updateModelStats);poll.setInterval(5000);connect(&poll,&QTimer::timeout,this,[this]{if(isVisible()&&!service.busy())service.refresh();updateModelStats();});poll.start();updateControls();updateModelStats();QTimer::singleShot(0,&service,&GpuPowerService::refresh);
}
const GpuPowerInfo *GpuPowerDialog::selected()const{const auto id=gpu->currentData().toString();for(const auto &card:service.devices())if(card.uuid==id)return &card;return nullptr;}
void GpuPowerDialog::updateDevices(){const auto id=gpu->currentData().toString();QSignalBlocker block(gpu);gpu->clear();for(const auto &card:service.devices())gpu->addItem(card.name+" · "+card.uuid,card.uuid);const auto index=gpu->findData(id);gpu->setCurrentIndex(index<0?0:index);if(index<0)dirty=false;updateControls();}
void GpuPowerDialog::updateControls(){
    const auto card=selected();const bool busy=service.busy();gpu->setEnabled(!busy);refresh->setEnabled(!busy);const bool supported=card&&card->adjustable();watts->setEnabled(supported&&!busy);preset->setEnabled(supported&&card->defaultLimit>0&&!busy);apply->setEnabled(supported&&!busy);restore->setEnabled(supported&&card->defaultLimit>=card->minimum&&card->defaultLimit<=card->maximum&&!busy);
    if(!card){details->setText("Доступные NVIDIA GPU не определены. Для AMD/Intel этот способ управления не поддерживается.");ratio->clear();return;}
    details->setText(card->name+"\n"+card->uuid+"\nМощность сейчас: "+measure(card->draw," Вт")+" · температура: "+measure(card->temperature," °C")+" · GPU: "+measure(card->load," %")+"\nЛимит драйвера: "+measure(card->limit," Вт")+" · заводской: "+measure(card->defaultLimit," Вт")+"\nРазрешено драйвером: "+measure(card->minimum," Вт")+" — "+measure(card->maximum," Вт")+(supported?QString():"\nДрайвер не сообщает поддерживаемый диапазон: изменение выключено."));
    if(supported){QSignalBlocker block(watts);watts->setRange(card->minimum,card->maximum);if(!dirty){watts->setValue(service.profileLimits.value(card->uuid).toDouble(card->limit));QSignalBlocker blockPreset(preset);preset->setCurrentIndex(0);}}updateRatio();
}
void GpuPowerDialog::updateRatio(){const auto card=selected();if(!card||!card->adjustable()){ratio->clear();return;}ratio->setText(QString("Будет отправлено %1 Вт").arg(watts->value(),0,'f',1)+(card->defaultLimit>0?QString(" (%1% заводского)").arg(watts->value()*100/card->defaultLimit,0,'f',1):QString())+" только на выбранную GPU. Заготовки ограничиваются min/max драйвера.");}
void GpuPowerDialog::updateModelStats(){const auto s=performance?performance->snapshot():ModelPerformanceSnapshot{};modelStats->setText("Модель: "+(s.model.isEmpty()?QString("не запущена"):s.model)+"\nПрефилл: "+measure(s.promptSpeed," ток/с")+" · генерация: "+measure(s.generationSpeed," ток/с")+(s.reportAgeMs>=0?QString(" · отчёт %1 с назад").arg(s.reportAgeMs/1000):QString())+"\nПосле изменения лимита завершите одинаковый новый запрос и дождитесь стабилизации температуры. Старый отчёт не измеряет новый лимит.");}
